class Solution {
public:
    vector<int> maxHammingDistances(vector<int>& nums, int m) {
        int N = 1 << m;
        vector<int> dist(N, -1);
        queue<int> q;
        for (int x : nums) {
            int complement = (N - 1) ^ x;
            if (dist[complement] == -1) { dist[complement] = 0; q.push(complement); }
        }
        while (!q.empty()) {
            int x = q.front(); q.pop();
            for (int b = 0; b < m; ++b) {
                int y = x ^ (1 << b);
                if (dist[y] == -1) { dist[y] = dist[x] + 1; q.push(y); }
            }
        }
        vector<int> ans;
        for (int x : nums) ans.push_back(m - dist[x]);
        return ans;
    }
};
